INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('fd0ff1dd-4856-4f51-b2a8-d914ed6a4d19', '051b209e-9985-44da-a832-ca884783cb98', 1, 'A Vontade Adormecida', NULL, '{"intro": "Psicologicamente, a vontade fraca \u00e9 fruto de decis\u00f5es adiadas.", "prayer": "Identifique uma \u00e1rea de pregui\u00e7a e a enfrente.", "practice": "Tome uma pequena decis\u00e3o hoje e cumpra-a imediatamente.", "reflection": "O maior inimigo da virtude n\u00e3o \u00e9 o erro, \u00e9 a in\u00e9rcia.", "journal_prompt": "O que voc\u00ea est\u00e1 evitando decidir?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d6c3dab7-7d22-4195-92f3-472f6de6bc16', '051b209e-9985-44da-a832-ca884783cb98', 2, 'O Ordenamento dos Afetos', NULL, '{"intro": "Desordem emocional gera ansiedade constante.", "prayer": "Ore pedindo a gra\u00e7a de amar o que \u00e9 eterno.", "practice": "Escolha um objeto em sua casa e o organize conscientemente.", "reflection": "Amar \u00e9 colocar as coisas no seu devido lugar.", "journal_prompt": "Seus amores est\u00e3o em ordem?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f9ed5e91-2888-4f7e-8499-85f71ffe2101', '051b209e-9985-44da-a832-ca884783cb98', 3, 'A Força do Hábito', NULL, '{"intro": "H\u00e1bitos s\u00e3o os trilhos sobre os quais nossa vida corre.", "prayer": "Pe\u00e7a const\u00e2ncia para as pequenas coisas.", "practice": "Inicie hoje um novo micro-h\u00e1bito positivo.", "reflection": "Somos o que fazemos repetidamente.", "journal_prompt": "Quais trilhos voc\u00ea est\u00e1 construindo hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8c2ff870-c484-4716-b31b-cf4d3ed019e5', '051b209e-9985-44da-a832-ca884783cb98', 4, 'O Silêncio Educativo', NULL, '{"intro": "Falar demais \u00e9 uma fuga do encontro consigo mesmo.", "prayer": "No sil\u00eancio, escute os batimentos do seu cora\u00e7\u00e3o.", "practice": "Fique 30 minutos sem falar nada, apenas observando.", "reflection": "Quem n\u00e3o domina a pr\u00f3pria l\u00edngua n\u00e3o domina a si mesmo.", "journal_prompt": "O que o seu barulho tenta esconder?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('5faa51eb-e635-4b43-bd47-627c5fa2efcf', '051b209e-9985-44da-a832-ca884783cb98', 5, 'A Obediência à Verdade', NULL, '{"intro": "Negar a realidade \u00e9 a raiz de todo sofrimento ps\u00edquico.", "prayer": "Abrace a sua fragilidade diante do Infinito.", "practice": "Aceite uma verdade dif\u00edcil sobre voc\u00ea hoje.", "reflection": "A liberdade real nasce de submeter-se ao que \u00e9 verdadeiro.", "journal_prompt": "Voc\u00ea prefere a mentira que conforta ou a verdade que cura?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('93c7e138-b527-4d3d-962e-df7b7447184a', '051b209e-9985-44da-a832-ca884783cb98', 6, 'A Coragem do Não', NULL, '{"intro": "A incapacidade de dizer n\u00e3o \u00e9 falta de identidade.", "prayer": "Pe\u00e7a for\u00e7a para sustentar suas escolhas.", "practice": "Diga n\u00e3o a algo que rouba o seu tempo hoje.", "reflection": "Dizer sim a tudo \u00e9 dizer n\u00e3o a si mesmo.", "journal_prompt": "A quem voc\u00ea est\u00e1 tentando agradar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7c57cc31-4852-4427-b2d7-02a25e3de1a5', '051b209e-9985-44da-a832-ca884783cb98', 7, 'O Caráter que se Ergue', NULL, '{"intro": "O homem formado \u00e9 aquele que se torna porto seguro para os outros.", "prayer": "Agrade\u00e7a pela jornada de fortalecimento.", "practice": "Fa\u00e7a algo por algu\u00e9m sem esperar nada em troca.", "reflection": "A forma\u00e7\u00e3o termina quando a sua vida se torna um dom.", "journal_prompt": "Quem pode contar com voc\u00ea hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('182be334-906b-447c-8bb7-7be26c2ed328', '0b8ddab7-b106-4873-bc4d-3987421d265d', 1, 'O Despertar Sagrado', NULL, '{"intro": "O primeiro pensamento do dia \u00e9 a semente de todas as suas a\u00e7\u00f5es.", "prayer": "Ofere\u00e7a o seu dia antes de sair da cama.", "practice": "N\u00e3o pegue no celular nos primeiros 15 minutos do dia.", "reflection": "A forma como voc\u00ea come\u00e7a o dia determina a sua alma.", "journal_prompt": "Qual \u00e9 a primeira coisa que voc\u00ea entrega ao mundo ao acordar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('57763fc6-f48e-436d-a54f-f3431216a562', '0b8ddab7-b106-4873-bc4d-3987421d265d', 2, 'O Dever do Momento', NULL, '{"intro": "A ansiedade nasce de querer estar no futuro e negligenciar o presente.", "prayer": "Pe\u00e7a a gra\u00e7a da presen\u00e7a de esp\u00edrito.", "practice": "Fa\u00e7a a sua tarefa mais chata com total aten\u00e7\u00e3o e amor.", "reflection": "A santidade est\u00e1 em fazer bem o que se deve fazer agora.", "journal_prompt": "Voc\u00ea est\u00e1 presente no que est\u00e1 fazendo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('99ec6d50-4d70-4e62-9da8-e7ddcc40d68d', '0b8ddab7-b106-4873-bc4d-3987421d265d', 3, 'As Pequenas Mortes', NULL, '{"intro": "Pequenos sacrif\u00edcios fortalecem a alma contra grandes quedas.", "prayer": "Ofere\u00e7a essa pequena morte pela convers\u00e3o de algu\u00e9m.", "practice": "Renuncie a uma pequena satisfa\u00e7\u00e3o hoje (um caf\u00e9, um doce, um coment\u00e1rio).", "reflection": "Cada ren\u00fancia \u00e9 um espa\u00e7o que se abre para a vida.", "journal_prompt": "O que voc\u00ea pode soltar para ser mais livre?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('690f82c8-60c1-4876-81ea-db828cbb8172', '0b8ddab7-b106-4873-bc4d-3987421d265d', 4, 'A Alimentação da Alma', NULL, '{"intro": "O que voc\u00ea l\u00ea, assiste e ouve molda a sua percep\u00e7\u00e3o da realidade.", "prayer": "Pe\u00e7a discernimento para o que voc\u00ea deixa entrar pelos olhos.", "practice": "Leia 5 p\u00e1ginas de um livro espiritual em vez de rolar as redes sociais.", "reflection": "Voc\u00ea se torna o que voc\u00ea consome.", "journal_prompt": "Como est\u00e1 a sa\u00fade da sua alma hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('995d2b5f-1b4c-4a45-a32b-4454c650afc2', '0b8ddab7-b106-4873-bc4d-3987421d265d', 5, 'O Encontro no Meio do Dia', NULL, '{"intro": "A rotina nos engole se n\u00e3o criarmos ilhas de sil\u00eancio.", "prayer": "Recite o Angelus ou uma ora\u00e7\u00e3o curta de entrega.", "practice": "Pare tudo por 2 minutos ao meio-dia para uma ora\u00e7\u00e3o r\u00e1pida.", "reflection": "Uma pausa para respirar \u00e9 uma pausa para lembrar de Deus.", "journal_prompt": "Voc\u00ea se lembrou dEle hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('49208096-da61-4368-9311-7f68034f6a7e', '0b8ddab7-b106-4873-bc4d-3987421d265d', 6, 'A Caridade Ordinária', NULL, '{"intro": "O amor se prova na paci\u00eancia com quem est\u00e1 ao nosso lado.", "prayer": "Pe\u00e7a para ver Cristo no pr\u00f3ximo.", "practice": "Fa\u00e7a um elogio sincero a algu\u00e9m que convive com voc\u00ea.", "reflection": "N\u00e3o espere grandes ocasi\u00f5es para amar.", "journal_prompt": "Quem voc\u00ea amou hoje de forma concreta?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d71cbf89-8f87-414f-8eeb-675a3959172a', '0b8ddab7-b106-4873-bc4d-3987421d265d', 7, 'O Exame da Noite', NULL, '{"intro": "O fim do dia \u00e9 o tempo da colheita e do perd\u00e3o.", "prayer": "Pe\u00e7a perd\u00e3o pelas falhas e agrade\u00e7a pelas vit\u00f3rias.", "practice": "Reveja o seu dia antes de dormir: onde houve amor? Onde faltou?", "reflection": "Ningu\u00e9m melhora o que n\u00e3o avalia.", "journal_prompt": "Se hoje fosse o seu \u00faltimo dia, voc\u00ea estaria em paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('12bea220-594b-4e61-952f-98f4fdca8436', '150f78d3-019b-40c0-962e-a83576309ea5', 1, 'O Centro de Gravidade', NULL, '{"intro": "O cora\u00e7\u00e3o \u00e9 o centro de comando de todas as nossas decis\u00f5es.", "prayer": "Pe\u00e7a para ancorar seu cora\u00e7\u00e3o na Verdade.", "practice": "Observe para onde o seu pensamento foge quando voc\u00ea est\u00e1 livre.", "reflection": "Onde est\u00e1 o teu tesouro, a\u00ed estar\u00e1 o teu cora\u00e7\u00e3o.", "journal_prompt": "O que ocupa o trono do seu cora\u00e7\u00e3o hoje?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('62d23419-0510-4f35-9098-8111d5a7a3c8', '150f78d3-019b-40c0-962e-a83576309ea5', 2, 'A Ferida Aberta', NULL, '{"intro": "A vulnerabilidade \u00e9 a porta de entrada para a gra\u00e7a.", "prayer": "Mostre a Ele o seu cora\u00e7\u00e3o partido.", "practice": "N\u00e3o esconda a sua tristeza hoje; sinta-a diante dEle.", "reflection": "\u00c9 pela rachadura no cora\u00e7\u00e3o que a luz entra.", "journal_prompt": "O que voc\u00ea est\u00e1 tentando proteger com tanto esfor\u00e7o?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('707485e8-6dc0-4b5e-9dc4-f69cf221bcf0', '150f78d3-019b-40c0-962e-a83576309ea5', 3, 'A Pureza da Intenção', NULL, '{"intro": "Muitas vezes fazemos coisas boas por motivos ego\u00edstas.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o puro e reto.", "practice": "Escolha uma tarefa e a realize com a inten\u00e7\u00e3o de agradar a Deus.", "reflection": "Faze o que fazes, por amor e s\u00f3 por amor.", "journal_prompt": "Por que voc\u00ea faz o que faz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b8cf5df7-c0a4-43ad-b4f3-6e93e7a839a2', '150f78d3-019b-40c0-962e-a83576309ea5', 4, 'O Coração que Escuta', NULL, '{"intro": "Escutar \u00e9 a forma mais profunda de amar.", "prayer": "Escute o sil\u00eancio de Deus no seu peito.", "practice": "Escute algu\u00e9m hoje sem interromper, sem julgar.", "reflection": "O amor tem ouvidos que a raz\u00e3o desconhece.", "journal_prompt": "Voc\u00ea est\u00e1 realmente ouvindo ou apenas esperando sua vez de falar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('f19f7093-d270-46d1-9ce8-7a088991e5d3', '150f78d3-019b-40c0-962e-a83576309ea5', 5, 'A Fortaleza Mansa', NULL, '{"intro": "A mansid\u00e3o \u00e9 o dom\u00ednio total das pr\u00f3prias paix\u00f5es.", "prayer": "Pe\u00e7a um cora\u00e7\u00e3o manso e humilde.", "practice": "Responda com do\u00e7ura a uma provoca\u00e7\u00e3o hoje.", "reflection": "A verdadeira for\u00e7a n\u00e3o \u00e9 a que grita, \u00e9 a que sustenta.", "journal_prompt": "A sua for\u00e7a vem do medo ou da paz?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('16373f39-c20d-4ca5-97e1-f294dcc349d4', '150f78d3-019b-40c0-962e-a83576309ea5', 6, 'A Alegria Profunda', NULL, '{"intro": "A alegria crist\u00e3 \u00e9 uma decis\u00e3o, n\u00e3o um sentimento passageiro.", "prayer": "Agrade\u00e7a por 5 pequenas alegrias do dia.", "practice": "Sorria para tr\u00eas estranhos hoje.", "reflection": "Um cora\u00e7\u00e3o triste \u00e9 um alvo f\u00e1cil para o mal.", "journal_prompt": "Onde voc\u00ea busca a sua alegria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
